import { DEFAULT_DEV_SHELL_PORT } from "./ports.js";
/** The registry for a worker's blocks, with unique localhost hostnames. */
export function buildBlockRegistry(blocks, port = DEFAULT_DEV_SHELL_PORT) {
    const used = new Set();
    return blocks.map(capability => {
        const stem = capability.key
            .toLowerCase()
            .replace(/[^a-z0-9-]+/g, "-")
            .replace(/^-+|-+$/g, "")
            .slice(0, 63)
            .replace(/-+$/g, "") || "block";
        let hostname = stem;
        let suffix = 1;
        // Distinct capability keys can normalize to the same hostname.
        // Add a suffix to keep hostnames unique within the 63-character label limit.
        while (used.has(hostname)) {
            const ending = `-${++suffix}`;
            hostname = stem.slice(0, 63 - ending.length).replace(/-+$/g, "") + ending;
        }
        used.add(hostname);
        return {
            key: capability.key,
            manifest: capability.config.manifest,
            name: capability.key,
            url: `http://${hostname}.localhost:${port}/`,
        };
    });
}
